// The Legacy Architect RVA logo, embedded as base64 rather than referenced
// by URL. Documents generated by the Document Converter and Life Manual
// Generator are meant to be downloaded and opened anywhere — locally with
// no network connection, attached to an email (where remote images are
// commonly blocked by default), or on a different machine entirely. A
// remote URL works when tested directly but fails silently in exactly
// those real-world cases, so the logo needs to travel with the file.
export const LOGO_DATA_URI = "data:image/png;base64,";

// QR code linking to legacyarchitectrva.com, used on the closing page of
// generated documents.
export const QR_CODE_DATA_URI = "data:image/png;base64,";
